export const meta = {
  name: 'treams-rs-release-review',
  description: 'Final release-readiness review of treams-rs PR #1: dimension finders, then adversarial verification',
  phases: [
    { title: 'Find', detail: 'one reviewer per release dimension' },
    { title: 'Verify', detail: 'skeptical verification of every finding' },
  ],
}

const ROOT = 'treams-rs-review'
const COMMON = `
You are reviewing the treams-rs repository for its FIRST public PyPI release (PR https://github.com/yaugenst/treams-rs/pull/1, head f9b43088, base 76ed0e82).
treams-rs is a Rust port of the treams T-matrix electromagnetic scattering library with a Python interface (maturin/PyO3) and analytic gradients via optional Advect/JAX/PyTorch/Autograd adapters.

Repository checkout to review (detached at the PR head, treat as READ-ONLY): ${ROOT}
Rules:
- Do NOT edit, create or delete files anywhere inside ${ROOT} or treams-rs (another agent is active there). Scratch work goes under treams-review-<your-dimension>/ only.
- You may run read-only commands, git log/show/diff, rg, and Python snippets with .venv/bin/python (treams_rs 0.1.0 built from this head is installed there, plus dev deps). For pytest use: cd ${ROOT} && .venv/bin/python -m pytest <paths> -q -p no:cacheprovider. A uv 0.12.22 binary (required by the repo) is at installed tools: uv. Do not run cargo builds against the main checkout's target dir.
- Hosted CI is green on this head (40 checks pass; one arm64 wheel job retrying for a network failure). The author and a previous agent already ran broad audits, so do not report style nits or restate passing checks. Hunt for things that would actually hurt a first public release: broken install/import, wrong metadata, release automation that will fail or publish the wrong thing, incorrect physics or gradients, misleading docs claims, licensing/attribution gaps, leaked private info.
- Every finding must cite file:line evidence and a concrete failure scenario (inputs/state -> wrong outcome). Prefer verifying by running something over reasoning. If you cannot substantiate a suspicion, drop it.
- Severity: blocker (must fix before publishing), high (should fix before publishing), medium (fix soon, fine to ship), low.
- Return at most 10 findings, most severe first. An empty list is a valid answer.
`

const FINDINGS = {
  type: 'object',
  properties: {
    findings: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          title: { type: 'string' },
          severity: { type: 'string', enum: ['blocker', 'high', 'medium', 'low'] },
          file: { type: 'string' },
          line: { type: 'integer' },
          evidence: { type: 'string', description: 'what you read or ran, with outputs' },
          failure_scenario: { type: 'string' },
          suggested_fix: { type: 'string' },
        },
        required: ['title', 'severity', 'file', 'evidence', 'failure_scenario', 'suggested_fix'],
      },
    },
    checked: { type: 'string', description: 'brief list of what you checked and found fine' },
  },
  required: ['findings', 'checked'],
}

const VERDICT = {
  type: 'object',
  properties: {
    real: { type: 'boolean' },
    severity: { type: 'string', enum: ['blocker', 'high', 'medium', 'low', 'not-an-issue'] },
    reasoning: { type: 'string', description: 'what you ran/read to confirm or refute, with outputs' },
    corrected_fix: { type: 'string' },
  },
  required: ['real', 'severity', 'reasoning'],
}

const DIMENSIONS = [
  { key: 'packaging', prompt: `Dimension: PACKAGING AND DISTRIBUTION. Check pyproject.toml, Cargo.toml files (workspace and crates), maturin config, version consistency everywhere a version appears (pyproject dynamic version source, Cargo versions, CHANGELOG.md, CITATION.cff, llms.txt, __version__, docs), Python/NumPy bounds and optional extras vs what the code imports, sdist and wheel contents (build an sdist into /tmp with uvx/uv-run maturin sdist and inspect it; inspect any locally built wheel if available), license-files and third-party notices completeness, typing markers (py.typed, .pyi coverage), excluded files, and whether a clean NumPy-only install can import treams_rs and run the README example without optional frameworks.` },
  { key: 'release-automation', prompt: `Dimension: RELEASE AUTOMATION. Read every workflow in .github/workflows (ci.yml, native-wheels.yml, release-candidate.yml, publish-release.yml, docs.yml, deploy-docs.yml, formal.yml) and any scripts they call, plus docs/development/releasing.md and RELEASING.md. Simulate the FIRST release end to end: tag/version checks, wheel matrix and sdist, TestPyPI then PyPI promotion of the same artifacts (trusted publishing, environments, permissions, id-token), GitHub release creation, docs deployment with mike (first deploy when gh-pages does not exist yet, the latest alias, versions.json, Pages artifact), concurrency and re-run behavior. Look for steps that will fail on the first run, publish the wrong artifact, leak permissions, or reference nonexistent secrets/environments. Check action pinning and script-injection via untrusted inputs.` },
  { key: 'public-surface', prompt: `Dimension: PUBLIC FACE ON PYPI AND GITHUB. README.md as PyPI renders it (relative links and images break on PyPI; badges; code examples correct and runnable), project URLs (do they resolve after the first release, e.g. docs /latest/), CHANGELOG.md accuracy for 0.1.0, CITATION.cff validity, attribution to the original treams authors and LICENSE.treams correctness, SECURITY.md/CONTRIBUTING.md/CODE_OF_CONDUCT.md contacts and instructions, llms.txt, and the python -m treams_rs CLI help/discovery. Run the README Python examples with the venv interpreter.` },
  { key: 'autodiff-dispatch', prompt: `Dimension: AUTODIFF BACKEND AUTO-SELECTION (newest, highest-risk feature; see commit cd0d780 "feat: select optional autodiff backends from input values" and python/treams_rs/ adapter modules advect/jax/torch/autograd and the dispatch code). Verify: optional frameworks are never imported unless the caller already imported/used them; NumPy-only calls work with no frameworks installed; mixed inputs (e.g. JAX + torch, tracer + plain numpy, float32 inputs, complex inputs, nested lists) are rejected or handled consistently with clear errors; jit/vmap/grad behaviour claims in docs match reality; thread safety of any caches; that gradients from auto-selected paths match the explicit adapter modules. Run focused experiments with the venv (it has advect, jax, torch, autograd installed if the dev env does; check) and the relevant tests.` },
  { key: 'docs-accuracy', prompt: `Dimension: DOCUMENTATION ACCURACY. Sample the user-facing docs (docs/index.md, getting-started/, coming-from-treams/, guide/, differentiation/, validation/, performance/index.md) and check that claims match the code and the evidence: function names and signatures exist (compare against python/treams_rs and the .pyi stubs and support_catalog()), statements of what is unsupported are true, numbers quoted (speedups, timings, test counts) match the evidence files they cite, cross-links resolve, and install instructions work. Run tests/api/test_docs.py with the venv to confirm executable fences pass. Report factual errors and misleading claims only, not prose style.` },
  { key: 'native-robustness', prompt: `Dimension: NATIVE CODE ROBUSTNESS AT THE PYTHON BOUNDARY. Review crates/treams-py (PyO3 bindings, ufuncs) and the boundary into crates/treams-core: Rust panics reaching Python (should become exceptions, never abort the interpreter), unsafe blocks and their invariants, GIL release with borrowed NumPy buffers, integer overflow on user-sized inputs (lmax, number of particles) leading to huge allocations, NaN/inf inputs, non-contiguous or read-only arrays, dtype handling (int32 on Windows, float32), and thread-pool configuration races. Try adversarial inputs from Python with the venv to see if anything crashes the interpreter (run each in a subprocess so a crash does not kill you).` },
  { key: 'public-repo-hygiene', prompt: `Dimension: PUBLIC REPOSITORY HYGIENE. The repo was just made public. Scan the tracked tree (git ls-files) and the 96 commits on the release branches for: secrets/tokens, private emails or names beyond intended authorship, internal hostnames/paths (e.g. /home/<user>, private URLs), leftover temporary/scratch files, large binary blobs that bloat clones, files that should be gitignored (dist/, target/, site/), AGENTS.md or agent instructions that leak private context, and licensing headers for vendored third_party code. Also check that benchmark/evidence files do not embed machine-identifying info that the PR says was removed.` },
]

const results = await pipeline(
  DIMENSIONS,
  d => agent(`${COMMON}\n${d.prompt}`, { label: `find:${d.key}`, phase: 'Find', schema: FINDINGS }),
  (review, d) => {
    if (!review) return []
    log(`${d.key}: ${review.findings.length} finding(s)`)
    return parallel(review.findings.map(f => () => {
      const lenses = (f.severity === 'blocker' || f.severity === 'high')
        ? ['reproduce it: run or read exactly what is needed to confirm the failure scenario actually happens at this head', 'impact: assume it is real and judge whether it actually matters for a first public 0.1.0 release, and whether the suggested fix is correct and minimal']
        : ['reproduce it: run or read exactly what is needed to confirm the failure scenario actually happens at this head']
      return parallel(lenses.map(lens => () => agent(
        `${COMMON}\nYou are a skeptical verifier. Try to REFUTE this finding from the ${d.key} review. Lens: ${lens}. Default to real=false if you cannot substantiate it.\n\nFinding: ${JSON.stringify(f, null, 2)}`,
        { label: `verify:${d.key}:${f.title.slice(0, 40)}`, phase: 'Verify', schema: VERDICT })))
        .then(vs => ({ dimension: d.key, ...f, verdicts: vs.filter(Boolean) }))
    })).then(items => ({ dimension: d.key, checked: review.checked, items }))
  },
)

return results.filter(Boolean)
